---@class MathUtil
MathUtil = {}
MathUtil.DEG2RAD = 0.01745329
MathUtil.RAD2DEG = 57.29577

---随机n个[low,high]范围的整数
---@param low number
---@param high number
---@param n number
function MathUtil:randomIntRepeat(low, high, n)
    local result = {}
    for i = 1, n do
        table.insert(result, math.random(low, high))
    end
    return result
end

---@param n number
---@param low number
---@param high number
function MathUtil:bound(n, low, high)
    if low >= high then
        return n
    end
    if n <= low then
        n = low
    end
    if n >= high then
        n = high
    end
    return n
end

---@param low number
---@param high number
function MathUtil:createTable(low, high)
    local result = {}
    for i = low, high do
        table.insert(result, i)
    end
    return result
end

---随机n个[low,high]范围的不重复的整数
---@param low number
---@param high number
---@param n number
function MathUtil:randomIntNoRepeat(low, high, n)
    local size = high - low + 1
    if n > size then
        return nil
    end

    local tb = MathUtil:createTable(low, high)

    local result = {}
    for i = 1, n do
        local index = math.random(#tb)
        tb[index], tb[#tb] = tb[#tb], tb[index]
        table.insert(result, tb[#tb])
        table.remove(tb)
    end
    return result
end

--在矩形范围内随机count个不重复的点

---@param minX number
---@param maxX number
---@param minZ number
---@param maxZ number
---@param count number
function MathUtil:randomInRect(minX, maxX, minZ, maxZ, count)
    local result = {}

    if (maxX - minX + 1) * (maxZ - minZ + 1) < count then
        return result
    end

    local index = 1
    while (index <= count)
    do
        local randomX = math.random(minX, maxX)
        local randomZ = math.random(minZ, maxZ)
        local pt = PointUtil:newPoint(randomX, randomZ)
        if PointUtil:isTableHavePoint(result, pt) == false then
            table.insert(result, pt)
            index = index + 1
        end
    end

    return result
end

