--在圆内随机一个点

---@param pos Vector3
---@param radius number
function MathUtil:randomInCircle(pos, radius)
    local resultX = math.random(-radius, radius)
    local resultY = math.sqrt(math.pow(radius, 2) - math.pow(resultX, 2))
    resultY = math.random(-resultY, resultY)
    return VectorUtil.newVector3(resultX + pos.x, pos.y, resultY + pos.z)
end

---在圆内随机一个点,随机结果是非整数
---@param pos Vector3
---@param radius number
function MathUtil:randomDoubleInCircle(pos, radius)
    local resultX = HostApi.random("random", -radius * 100, radius * 100) / 100
    local resultY = HostApi.random("random", -radius * 100, radius * 100) / 100
    return VectorUtil.newVector3(resultX + pos.x, pos.y, resultY + pos.z)
end

--2d点距离的平方
---@param pos1 Vector3
---@param pos2 Vector3
function MathUtil:distanceSquare2d(pos1, pos2)
    local result = math.pow((pos1.x - pos2.x), 2) + math.pow((pos1.z - pos2.z), 2)
    return result
end

--3d点距离的平方
---@param pos1 Vector3
---@param pos2 Vector3
function MathUtil:distanceSquare3d(pos1, pos2)
    local result = math.pow((pos1.x - pos2.x), 2) + math.pow((pos1.y - pos2.y), 2) + math.pow((pos1.z - pos2.z), 2)
    return result
end

--检测是否在距离内
---@param pos1 Vector3
---@param pos2 Vector3
---@param dis number
function MathUtil:checkDisLessThan(pos1, pos2, dis)
    return MathUtil:distanceSquare3d(pos1, pos2) < math.pow(dis, 2)
end

function MathUtil:isCollision(entity1, entity2)
    if entity1 == nil or entity2 == nil then
        return false
    end

    local pos1 = entity1:getPosition()
    local pos2 = entity2:getPosition()

    local scale1 = entity1:getScale()
    local scale2 = entity2:getScale()
    local width1 = entity1:getWidth() * scale1
    local width2 = entity2:getWidth() * scale2
    local height1 = entity1:getHeight() * scale1
    local height2 = entity2:getHeight() * scale2

    local isCollision = (math.abs(pos1.x - pos2.x) < (width1 + width2) * 0.5)
            and (math.abs(pos1.z - pos2.z) < (width1 + width2) * 0.5)
            and (math.abs(pos1.y - pos2.y) < (height1 + height2) * 0.5)

    return isCollision
end

function MathUtil:checkPosInRect(pos, rect)
    return (pos.x > rect.left and pos.x < rect.right) and (pos.z > rect.bottom and pos.z < rect.top)
end

---向量点乘
---@param v1 Vector3
---@param v2 Vector3
function MathUtil.GetVector3Dot(v1, v2)
    return v1.x * v2.x + v1.y * v2.y + v1.z * v2.z
end

---向量叉乘
---@param v1 Vector3
---@param v2 Vector3
function MathUtil.GetVector3Cross(v1, v2)
    local v3 = { x = v1.y * v2.z - v2.y * v1.z, y = v2.x * v1.z - v1.x * v2.z, z = v1.x * v2.y - v2.x * v1.y }
    return v3
end

---向量的模
---@param v Vector3
function MathUtil.GetVector3Module(v)
    return math.sqrt(v.x * v.x + v.y * v.y + v.z * v.z)
end

---求两向量间夹角
---@param v1 Vector3
---@param v2 Vector3
function MathUtil.GetVector3Angle(v1, v2)
    local cos = MathUtil.GetVector3Dot(v1, v2) / (MathUtil.GetVector3Module(v1) * MathUtil.GetVector3Module(v2))
    return math.acos(cos) * 180 / math.pi
end

---@param vector3 Vector3
function MathUtil.getForwardPos(vector3, yaw, distance)
    local f1 = -math.sin(yaw * math.pi / 180)
    local f2 = math.cos(yaw * math.pi / 180)
    local dx = f1 * distance
    local dz = f2 * distance
    ---@type Vector3
    local newPos = TableUtil.copyTable(vector3)
    newPos.x = newPos.x + dx
    newPos.z = newPos.z + dz
    return newPos
end

---@param vector3 Vector3
function MathUtil.getBackPos(vector3, yaw, distance)
    return MathUtil.getForwardPos(vector3, yaw - 180, distance)
end

---@param vector3 Vector3
function MathUtil.getLeftPos(vector3, yaw, distance)
    return MathUtil.getForwardPos(vector3, yaw - 90, distance)
end

---@param vector3 Vector3
function MathUtil.getRightPos(vector3, yaw, distance)
    return MathUtil.getForwardPos(vector3, yaw + 90, distance)
end

---@param startPos Vector3
---@param endPos Vector3
---@return Vector3
function MathUtil.getProcessPos(startPos, endPos, process)
    local x = startPos.x + (endPos.x - startPos.x) * process
    local y = startPos.y + (endPos.y - startPos.y) * process
    local z = startPos.z + (endPos.z - startPos.z) * process
    return VectorUtil.newVector3(x, y, z)
end

return MathUtil